GRAMMAR_COURSE = [{'id': 'zh-hsk1-01', 'order': 1, 'level': 'HSK1', 'category': 'Câu cơ bản', 'title': 'Trật tự SVO cơ bản', 'objective_vi': 'Nắm thứ tự Chủ ngữ + Động từ + Tân ngữ và tránh bê nguyên trật tự tiếng Việt vào câu Trung.'}, {'id': 'zh-hsk1-02', 'order': 2, 'level': 'HSK1', 'category': 'Câu cơ bản', 'title': '是: câu định danh', 'objective_vi': 'Dùng 是 để nối chủ ngữ với danh từ hoặc thông tin định danh; không dùng 是 trước tính từ thông thường.'}, {'id': 'zh-hsk1-03', 'order': 3, 'level': 'HSK1', 'category': 'Sở hữu / tồn tại', 'title': '有: có và sở hữu', 'objective_vi': 'Dùng 有 để diễn tả sở hữu hoặc sự tồn tại trong cấu trúc cơ bản.'}, {'id': 'zh-hsk1-04', 'order': 4, 'level': 'HSK1', 'category': 'Trợ từ', 'title': '的: sở hữu và bổ nghĩa', 'objective_vi': 'Dùng 的 trong cụm sở hữu và bổ nghĩa danh từ ở mức cơ bản.'}, {'id': 'zh-hsk1-05', 'order': 5, 'level': 'HSK1', 'category': 'Chỉ định', 'title': '这 / 那 / 哪', 'objective_vi': 'Phân biệt 这, 那 và 哪 khi chỉ người, vật và lựa chọn.'}, {'id': 'zh-hsk1-06', 'order': 6, 'level': 'HSK1', 'category': 'Câu hỏi', 'title': '吗 và 呢', 'objective_vi': 'Tạo câu hỏi yes/no với 吗 và dùng 呢 trong câu hỏi ngắn theo ngữ cảnh.'}, {'id': 'zh-hsk1-07', 'order': 7, 'level': 'HSK1', 'category': 'Câu hỏi', 'title': '谁 / 什么 / 哪 / 几', 'objective_vi': 'Đặt từ để hỏi đúng vị trí thay vì đưa toàn bộ từ hỏi lên đầu câu.'}, {'id': 'zh-hsk1-08', 'order': 8, 'level': 'HSK1', 'category': 'Trật tự từ', 'title': 'Thời gian và địa điểm trong câu', 'objective_vi': 'Sắp xếp thời gian, địa điểm và hành động theo trật tự tự nhiên trong câu tiếng Trung.'}, {'id': 'zh-hsk2-09', 'order': 9, 'level': 'HSK2', 'category': 'Trợ từ thể', 'title': '了: hoàn thành và thay đổi', 'objective_vi': 'Nhận biết 了 sau động từ và 了 cuối câu trong các tình huống cơ bản.'}, {'id': 'zh-hsk2-10', 'order': 10, 'level': 'HSK2', 'category': 'Tiếp diễn', 'title': '在 / 正在 / 呢', 'objective_vi': 'Diễn tả hành động đang diễn ra bằng 在, 正在 và 呢.'}, {'id': 'zh-hsk2-11', 'order': 11, 'level': 'HSK2', 'category': 'Động từ năng nguyện', 'title': '会 / 能 / 可以', 'objective_vi': 'Phân biệt khả năng đã học, khả năng theo điều kiện và sự cho phép.'}, {'id': 'zh-hsk2-12', 'order': 12, 'level': 'HSK2', 'category': 'So sánh', 'title': '比: so sánh cơ bản', 'objective_vi': 'Tạo câu A 比 B + tính từ và tránh thêm 很 sai chỗ.'}, {'id': 'zh-hsk2-13', 'order': 13, 'level': 'HSK2', 'category': 'Lượng từ', 'title': 'Lượng từ thông dụng', 'objective_vi': 'Dùng 个, 本, 杯, 张, 件, 位 và cấu trúc số + lượng từ + danh từ.'}, {'id': 'zh-hsk2-14', 'order': 14, 'level': 'HSK2', 'category': 'Phó từ', 'title': '也 / 都 / 还', 'objective_vi': 'Đặt 也, 都 và 还 đúng vị trí trước vị ngữ.'}, {'id': 'zh-hsk2-15', 'order': 15, 'level': 'HSK2', 'category': 'Liên kết', 'title': '因为…所以…', 'objective_vi': 'Nối nguyên nhân và kết quả rõ ràng bằng 因为 và 所以.'}, {'id': 'zh-hsk2-16', 'order': 16, 'level': 'HSK2', 'category': 'Mức độ', 'title': '很 / 太…了 / 非常', 'objective_vi': 'Biểu đạt mức độ tự nhiên với tính từ và tránh dịch từng chữ từ tiếng Việt.'}, {'id': 'zh-hsk3-17', 'order': 17, 'level': 'HSK3', 'category': 'Trợ từ thể', 'title': '过: kinh nghiệm', 'objective_vi': 'Dùng 过 để nói về trải nghiệm đã từng xảy ra, khác với 了.'}, {'id': 'zh-hsk3-18', 'order': 18, 'level': 'HSK3', 'category': 'Trạng thái', 'title': '着: trạng thái duy trì', 'objective_vi': 'Dùng 着 để mô tả trạng thái đang được duy trì.'}, {'id': 'zh-hsk3-19', 'order': 19, 'level': 'HSK3', 'category': 'Bổ ngữ kết quả', 'title': '完 / 好 / 到 / 见', 'objective_vi': 'Dùng bổ ngữ kết quả để cho biết hành động đạt kết quả gì.'}, {'id': 'zh-hsk3-20', 'order': 20, 'level': 'HSK3', 'category': 'Bổ ngữ xu hướng', 'title': '来 / 去 và xu hướng đơn', 'objective_vi': 'Diễn tả hướng chuyển động so với vị trí người nói.'}, {'id': 'zh-hsk3-21', 'order': 21, 'level': 'HSK3', 'category': 'Cấu trúc song song', 'title': '一边…一边…', 'objective_vi': 'Diễn tả hai hành động diễn ra đồng thời.'}, {'id': 'zh-hsk3-22', 'order': 22, 'level': 'HSK3', 'category': 'Phạm vi', 'title': '除了…以外…', 'objective_vi': 'Diễn tả ngoại trừ hoặc ngoài ra bằng 除了…以外….'}, {'id': 'zh-hsk3-23', 'order': 23, 'level': 'HSK3', 'category': 'Biến đổi', 'title': '越来越…', 'objective_vi': 'Diễn tả xu hướng thay đổi tăng dần một cách tự nhiên.'}, {'id': 'zh-hsk3-24', 'order': 24, 'level': 'HSK3', 'category': '把字句', 'title': '把: giới thiệu', 'objective_vi': 'Dùng 把 khi muốn đưa đối tượng lên trước và nhấn mạnh cách xử lý hoặc kết quả.'}, {'id': 'zh-hsk4-25', 'order': 25, 'level': 'HSK4', 'category': '被字句', 'title': '被: câu bị động cơ bản', 'objective_vi': 'Dùng 被 để diễn tả bị động khi tác nhân hoặc kết quả là trọng tâm.'}, {'id': 'zh-hsk4-26', 'order': 26, 'level': 'HSK4', 'category': 'Nhấn mạnh', 'title': '是…的', 'objective_vi': 'Dùng 是…的 để nhấn mạnh thời gian, địa điểm, cách thức hoặc người thực hiện của sự việc đã xảy ra.'}, {'id': 'zh-hsk4-27', 'order': 27, 'level': 'HSK4', 'category': 'Thời điểm', 'title': '就 và 才', 'objective_vi': 'Phân biệt 就 và 才 để diễn tả sớm, nhanh, muộn hoặc điều kiện.'}, {'id': 'zh-hsk4-28', 'order': 28, 'level': 'HSK4', 'category': 'Quan hệ thời gian', 'title': '一…就…', 'objective_vi': 'Diễn tả hành động thứ hai xảy ra ngay sau hành động thứ nhất.'}, {'id': 'zh-hsk4-29', 'order': 29, 'level': 'HSK4', 'category': 'Điều kiện', 'title': '只要…就…', 'objective_vi': 'Dùng điều kiện đủ với 只要…就….'}, {'id': 'zh-hsk4-30', 'order': 30, 'level': 'HSK4', 'category': 'Điều kiện', 'title': '如果…就…', 'objective_vi': 'Tạo câu điều kiện thực tế hoặc có khả năng xảy ra.'}, {'id': 'zh-hsk4-31', 'order': 31, 'level': 'HSK4', 'category': 'Nhượng bộ', 'title': '即使…也…', 'objective_vi': 'Diễn tả dù có điều kiện bất lợi thì kết quả vẫn không thay đổi.'}, {'id': 'zh-hsk4-32', 'order': 32, 'level': 'HSK4', 'category': 'Mạch văn', 'title': '首先 / 然后 / 最后', 'objective_vi': 'Tổ chức đoạn văn theo trình tự rõ ràng thay vì viết các câu rời rạc.'}, {'id': 'zh-hsk5-33', 'order': 33, 'level': 'HSK5', 'category': 'Bổ ngữ mức độ', 'title': '得: mô tả mức độ/kết quả', 'objective_vi': 'Dùng 得 sau động từ để mô tả mức độ hoặc trạng thái của hành động.'}, {'id': 'zh-hsk5-34', 'order': 34, 'level': 'HSK5', 'category': 'Bổ ngữ khả năng', 'title': 'V 得 / 不 + bổ ngữ', 'objective_vi': 'Phân biệt khả năng thực hiện kết quả với 能/可以.'}, {'id': 'zh-hsk5-35', 'order': 35, 'level': 'HSK5', 'category': 'Nhấn mạnh phạm vi', 'title': '连…都 / 也…', 'objective_vi': 'Dùng 连…都/也… để nhấn mạnh trường hợp cực đoan hoặc bất ngờ.'}, {'id': 'zh-hsk5-36', 'order': 36, 'level': 'HSK5', 'category': 'Tăng tiến', 'title': '不但…而且…', 'objective_vi': 'Kết nối hai ý tăng tiến trong câu và đoạn văn.'}, {'id': 'zh-hsk5-37', 'order': 37, 'level': 'HSK5', 'category': 'Lựa chọn', 'title': '与其…不如…', 'objective_vi': 'Biểu đạt lựa chọn ưu tiên giữa hai phương án.'}, {'id': 'zh-hsk5-38', 'order': 38, 'level': 'HSK5', 'category': 'Nguyên nhân đã rõ', 'title': '既然…就…', 'objective_vi': 'Dùng 既然…就… khi tiền đề đã được chấp nhận.'}, {'id': 'zh-hsk5-39', 'order': 39, 'level': 'HSK5', 'category': 'Bao quát', 'title': '无论…都…', 'objective_vi': 'Diễn tả kết quả không thay đổi dù điều kiện thay đổi.'}, {'id': 'zh-hsk5-40', 'order': 40, 'level': 'HSK5', 'category': 'Chủ đề / góc nhìn', 'title': '对…来说 / 关于…', 'objective_vi': 'Mở chủ đề và xác định góc nhìn rõ ràng trong văn viết.'}, {'id': 'zh-hsk6-41', 'order': 41, 'level': 'HSK6', 'category': 'Nguyên nhân nhấn mạnh', 'title': '之所以…是因为…', 'objective_vi': 'Nêu kết quả trước rồi giải thích nguyên nhân với cấu trúc nhấn mạnh.'}, {'id': 'zh-hsk6-42', 'order': 42, 'level': 'HSK6', 'category': 'So sánh văn viết', 'title': '与…相比 / 相比之下', 'objective_vi': 'So sánh hai đối tượng hoặc xu hướng theo phong cách viết rõ ràng.'}, {'id': 'zh-hsk6-43', 'order': 43, 'level': 'HSK6', 'category': '把 / 被 nâng cao', 'title': '把 / 被 với bổ ngữ phức', 'objective_vi': 'Kết hợp 把 hoặc 被 với bổ ngữ kết quả, xu hướng và thông tin bổ sung.'}, {'id': 'zh-hsk6-44', 'order': 44, 'level': 'HSK6', 'category': 'Liên kết học thuật', 'title': '因此 / 然而 / 此外 / 尽管', 'objective_vi': 'Chọn từ nối phù hợp quan hệ logic và mức độ trang trọng.'}, {'id': 'zh-hsk6-45', 'order': 45, 'level': 'HSK6', 'category': 'Cấu trúc chủ đề', 'title': 'Topic-comment và lược bỏ', 'objective_vi': 'Viết câu tự nhiên bằng cách quản lý chủ đề và tránh lặp chủ ngữ không cần thiết.'}, {'id': 'zh-hsk6-46', 'order': 46, 'level': 'HSK6', 'category': 'Định ngữ', 'title': 'Định ngữ dài trước 的', 'objective_vi': 'Sắp xếp định ngữ dài trước danh từ mà vẫn giữ câu dễ đọc.'}, {'id': 'zh-hsk6-47', 'order': 47, 'level': 'HSK6', 'category': 'Văn viết', 'title': '由于 / 从而 / 由此', 'objective_vi': 'Dùng liên kết nguyên nhân-kết quả mang sắc thái văn viết.'}, {'id': 'zh-hsk6-48', 'order': 48, 'level': 'HSK6', 'category': 'Sắc thái', 'title': '甚至 / 何况 / 未必', 'objective_vi': 'Biểu đạt nhấn mạnh, suy rộng và mức độ chắc chắn tinh tế.'}, {'id': 'zh-hsk79-49', 'order': 49, 'level': 'HSK7-9', 'category': 'Cú pháp nâng cao', 'title': 'Trật tự định ngữ phức', 'objective_vi': 'Quản lý nhiều lớp bổ nghĩa trước danh từ để câu chính xác và không nặng nề.'}, {'id': 'zh-hsk79-50', 'order': 50, 'level': 'HSK7-9', 'category': 'Liên kết văn bản', 'title': '其 / 该 / 此 và tham chiếu', 'objective_vi': 'Dùng từ tham chiếu văn viết để giảm lặp và tăng liên kết giữa câu.'}, {'id': 'zh-hsk79-51', 'order': 51, 'level': 'HSK7-9', 'category': 'Nhượng bộ nâng cao', 'title': '即便 / 哪怕 / 纵然', 'objective_vi': 'Phân biệt sắc thái của các cấu trúc nhượng bộ nâng cao.'}, {'id': 'zh-hsk79-52', 'order': 52, 'level': 'HSK7-9', 'category': 'Điều kiện giới hạn', 'title': '除非…否则…', 'objective_vi': 'Diễn tả điều kiện cần và hậu quả nếu điều kiện không được đáp ứng.'}, {'id': 'zh-hsk79-53', 'order': 53, 'level': 'HSK7-9', 'category': 'Lập luận song song', 'title': '一方面…另一方面…', 'objective_vi': 'Tổ chức hai mặt của một vấn đề cân đối và rõ ràng.'}, {'id': 'zh-hsk79-54', 'order': 54, 'level': 'HSK7-9', 'category': 'Góc nhìn học thuật', 'title': '就…而言 / 从…角度来看', 'objective_vi': 'Giới hạn phạm vi nhận định và trình bày góc nhìn theo văn phong học thuật.'}, {'id': 'zh-hsk79-55', 'order': 55, 'level': 'HSK7-9', 'category': 'Phong cách', 'title': 'Viết cô đọng, tránh lặp', 'objective_vi': 'Giảm đại từ, từ nối và cấu trúc lặp không cần thiết trong văn viết nâng cao.'}, {'id': 'zh-hsk79-56', 'order': 56, 'level': 'HSK7-9', 'category': 'Lập luận', 'title': 'Luận điểm → bằng chứng → phản biện → kết luận', 'objective_vi': 'Xây dựng đoạn/bài có luận điểm, dẫn chứng, xử lý ý đối lập và kết luận mạch lạc.'}]

